// Both exports merge their arguments into one object. The contract leaves
// `callbacks` open: it does not say whether, or when, either export calls a
// function it receives. That openness is the claim under test.
//
// The signatures accept any object, a function included, so every call in
// App.tsx is `tsc`-clean and nothing here duplicates a type diagnostic.
export declare function withDefaults(...sources: object[]): object;
export declare function withOverrides(base: object, overrides: object): object;
